// 369.26-15 guard: the mod's derived copies of the command registry and the section job canon are
// byte-equal to data/, every registry row has the fields the action list reads, and no count taken
// from the registry is written into the mod (counts are read at run time).
//
// The fix for a failing byte-equality arm is always: node ui/mindrian-workspace-mod/scripts/sync-assets.cjs
// (the registry is regenerated by the born-wired build and is never hand-edited).
//
// Plain counters, nonzero exit tail (house harness). Hyphens only.
'use strict';

const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const REPO = path.resolve(__dirname, '..');
const MOD = path.join(REPO, 'ui', 'mindrian-workspace-mod');
const FIX = 'fix: node ui/mindrian-workspace-mod/scripts/sync-assets.cjs';

let passed = 0;
let failed = 0;
function scenario(name, fn) {
  try {
    fn();
    passed += 1;
    process.stdout.write('  ok ' + name + '\n');
  } catch (err) {
    failed += 1;
    process.stdout.write('  FAIL ' + name + '\n    ' + String(err && err.message ? err.message : err).split('\n').join('\n    ') + '\n');
  }
}

function sameBytes(canonicalRel, derivedRel) {
  const a = path.join(REPO, canonicalRel);
  const b = path.join(REPO, derivedRel);
  assert.ok(fs.existsSync(a), canonicalRel + ' exists');
  assert.ok(fs.existsSync(b), derivedRel + ' exists (' + FIX + ')');
  assert.ok(fs.readFileSync(a).equals(fs.readFileSync(b)), derivedRel + ' differs from ' + canonicalRel + ' (' + FIX + ')');
}

// ---------- (1) byte equality of the derived assets ----------

scenario('assets/command-registry.json is byte-equal to data/command-registry.json', () => {
  sameBytes('data/command-registry.json', 'ui/mindrian-workspace-mod/assets/command-registry.json');
});

scenario('assets/section-job-canon.json is byte-equal to data/section-job-canon.json', () => {
  sameBytes('data/section-job-canon.json', 'ui/mindrian-workspace-mod/assets/section-job-canon.json');
});

scenario('sync-assets.cjs --check exits 0 and names both registry assets', () => {
  const script = path.join(MOD, 'scripts', 'sync-assets.cjs');
  assert.ok(fs.existsSync(script), 'scripts/sync-assets.cjs exists');
  const r = spawnSync(process.execPath, [script, '--check'], { encoding: 'utf8' });
  assert.strictEqual(r.status, 0, 'exit ' + r.status + ': ' + r.stdout + r.stderr);
  assert.ok(/command-registry\.json/.test(r.stdout), 'output names command-registry.json');
  assert.ok(/section-job-canon\.json/.test(r.stdout), 'output names section-job-canon.json');
});

// ---------- (2) the field contract ----------

function loadRegistry() {
  const file = path.join(REPO, 'data', 'command-registry.json');
  const parsed = JSON.parse(fs.readFileSync(file, 'utf8'));
  assert.ok(parsed && Array.isArray(parsed.commands), 'data/command-registry.json has a commands array');
  return parsed.commands;
}

// A row the list can draw carries a non-blank command and a non-blank body_shape and a list of jobs.
// jtbd_summary is read as data and may be absent: a row with no reason is not listed (the model
// drops it), so absence is reported here, never a failure of the registry itself.
scenario('every registry row has command, body_shape and a serves_jtbd list (informational: rows with no reason)', () => {
  const rows = loadRegistry();
  const bad = [];
  const noReason = [];
  for (const row of rows) {
    const name = row && typeof row.command === 'string' ? row.command : '(no command)';
    if (!row || typeof row.command !== 'string' || row.command.trim() === '') bad.push(name + ': command');
    else if (typeof row.body_shape !== 'string' || row.body_shape.trim() === '') bad.push(name + ': body_shape');
    else if (!Array.isArray(row.serves_jtbd)) bad.push(name + ': serves_jtbd is not a list');
    if (row && (typeof row.jtbd_summary !== 'string' || row.jtbd_summary.trim() === '')) noReason.push(name);
  }
  assert.deepStrictEqual(bad, [], 'rows missing a field the action list reads: ' + bad.join(', '));
  process.stdout.write('    rows with no jtbd_summary (not listed by the model): ' + (noReason.length === 0 ? 'none' : noReason.join(', ')) + '\n');
});

scenario('informational: distinct body_shape values and the non-methodology row count', () => {
  const rows = loadRegistry();
  const shapes = [...new Set(rows.map((r) => r.body_shape))].sort();
  const nonMethodology = rows.filter((r) => r.body_shape !== 'methodology').length;
  process.stdout.write('    body_shape values (' + shapes.length + '): ' + shapes.join(' | ') + '\n');
  process.stdout.write('    rows: ' + rows.length + ', non-methodology rows: ' + nonMethodology + '\n');
  assert.ok(shapes.includes('methodology'), 'the methodology marker is the body_shape value "methodology"');
});

scenario('the job canon has a sections map, each with a job_id', () => {
  const canon = JSON.parse(fs.readFileSync(path.join(REPO, 'data', 'section-job-canon.json'), 'utf8'));
  assert.ok(canon && typeof canon.sections === 'object' && canon.sections !== null, 'sections map');
  for (const [folder, v] of Object.entries(canon.sections)) {
    assert.ok(v && typeof v.job_id === 'string' && v.job_id.length > 0, folder + ' has a job_id');
  }
});

// ---------- (3) no registry count in the mod ----------

function stripComments(text) {
  return text.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[\s;,{(])\/\/[^\n]*/g, '$1');
}
function srcFiles(dir) {
  const out = [];
  if (!fs.existsSync(dir)) return out;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const abs = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...srcFiles(abs));
    else if (/\.tsx?$/.test(entry.name)) out.push(abs);
  }
  return out;
}
function literalHits(files, numbers) {
  const hits = [];
  const re = new RegExp('(^|[^\\w.])(' + numbers.join('|') + ')(?![\\w.])');
  for (const f of files) {
    const body = stripComments(fs.readFileSync(f, 'utf8'));
    body.split('\n').forEach((line, i) => {
      if (re.test(line)) hits.push(path.relative(MOD, f) + ':' + (i + 1) + ': ' + line.trim());
    });
  }
  return hits;
}

// The whole src/ is held to the total (114 as of 2026-10-06, read from the file now). The counts that
// double as layout numbers elsewhere (the context limit is 80) are held to the action list's own files.
scenario('no registry count is written into the mod (total across src; the derived counts in the action list files)', () => {
  const rows = loadRegistry();
  const total = rows.length;
  const nonMethodology = rows.filter((r) => r.body_shape !== 'methodology').length;
  const methodology = total - nonMethodology;
  const all = srcFiles(path.join(MOD, 'src'));
  const own = [
    path.join(MOD, 'src', 'pane', 'room', 'registry-model.ts'),
    path.join(MOD, 'src', 'pane', 'room', 'action-list.tsx'),
    path.join(MOD, 'src', 'pane', 'bodies', 'room.tsx'),
  ].filter((f) => fs.existsSync(f));
  const hitsTotal = literalHits(all, [String(total)]);
  const hitsOwn = literalHits(own, [String(nonMethodology), String(methodology)]);
  assert.deepStrictEqual(hitsTotal.concat(hitsOwn), [], 'a registry count is written in the mod');
});

scenario('the action list files read no hitl_shape and never submit', () => {
  const files = srcFiles(path.join(MOD, 'src'));
  const hits = [];
  for (const f of files) {
    const body = stripComments(fs.readFileSync(f, 'utf8'));
    if (/hitl_shape/.test(body)) hits.push(path.relative(MOD, f) + ': hitl_shape');
    if (/prompt\.submit/.test(body)) hits.push(path.relative(MOD, f) + ': prompt.submit');
  }
  assert.deepStrictEqual(hits, [], 'forbidden read or call');
});

process.stdout.write('\n' + passed + ' passed, ' + failed + ' failed\n');
process.exit(failed === 0 ? 0 : 1);
